#include <iostream>
#include <vector>
#include <algorithm>
#include <unordered_map>

using namespace std;
typedef long long ll;
const ll MOD = 1000000007;

ll sum_ll(ll a, ll b) {
    return (a + b) % MOD;
}

ll diff_ll(ll a, ll b) {
    a -= b;
    return (a < 0) ? a + MOD : a;
}

ll mul_ll(ll a, ll b) {
    return (a * b) % MOD;
}

ll pow_ll(ll base, ll exp) {
    if (exp == 0) return 1;
    if (exp & 1) return mul_ll(base, pow_ll(base, exp - 1));
    return pow_ll(mul_ll(base, base), exp >> 1);
}

ll inv_ll(ll x) {
    return pow_ll(x, MOD - 2);
}

int n_count;
vector<vector<ll>> matA;
ll T_array[8][1 << 7][1 << 7];
vector<unordered_map<ll,ll>> DP_map;
vector<int> family_size(1 << 7, 0);
vector<int> family_idx(1 << 7, 0);
vector<vector<int>> family_mask_list2;

void compute() {
    family_mask_list2.resize(n_count + 1);
    for (int mask=1; mask<(1<<n_count); ++mask) {
        family_size[mask] = family_size[mask>>1] + (mask & 1);
    }
    for (int mask=0; mask<(1<<n_count); ++mask) {
        family_idx[mask] = (int)family_mask_list2[family_size[mask]].size();
        family_mask_list2[family_size[mask]].push_back(mask);
    }
    for (int k=0; k<=n_count; ++k) {
        for (int i=0; i<(int)family_mask_list2[k].size(); ++i) {
            int cm=family_mask_list2[k][i];
            for (int mask=0; mask<(1<<n_count); ++mask) {
                ll ans=0;
                if ((mask & cm)==mask) continue;
                for (int x=0; x<n_count; ++x) {
                    if (cm & (1<<x)) continue;
                    if ((mask & (1<<x))==0) continue;
                    int newmask=cm | (1<<x);
                    ans |= (1ll << family_idx[newmask]);
                }
                T_array[k][i][mask]=ans;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin>>n_count;
    matA.resize(n_count);
    for (int i=0; i<n_count; ++i) {
        matA[i].resize(n_count);
        for (int j=0; j<n_count; ++j) {
            cin>>matA[i][j];
            matA[i][j]=mul_ll(matA[i][j],inv_ll(100));
        }
    }
    compute();
    DP_map.resize(n_count+1);
    DP_map[0][1]=1;
    for (int k=0; k<n_count; ++k) {
        for (int edges=0; edges<(1<<n_count); ++edges) {
            ll prob=1;
            for (int i=0; i<n_count; ++i) {
                if (edges & (1<<i))
                    prob=mul_ll(prob,matA[k][i]);
                else
                    prob=mul_ll(prob,diff_ll(1,matA[k][i]));
            }
            for (auto &S:DP_map[k]) {
                ll mask=S.first;
                ll newmask=0;
                ll p=mul_ll(prob,S.second);
                for (int i=0; i<(int)family_mask_list2[k].size(); ++i) {
                    if (mask & (1<<i))
                        newmask |= T_array[k][i][edges];
                }
                if (newmask != 0)
                    DP_map[k+1][newmask]=sum_ll(DP_map[k+1][newmask],p);
            }
        }
    }
    cout<<DP_map[n_count][1]<<endl;
    return 0;
}
